    to: z.iso.date(),
  })
  .check((payload) => {
    const { from, to } = payload.value;
    if (from > to) {
      payload.issues.push({
        code: "custom",
        input: payload.value,
        message: "from is after to",
        path: ["from"],
      });
    } else if ((Date.parse(to) - Date.parse(from)) / 86_400_000 >= MAX_RANGE_DAYS) {
      payload.issues.push({
        code: "custom",
        input: payload.value,
        message: `range is longer than ${MAX_RANGE_DAYS} days`,
